package com.astrsomn.starter.runtime.config;import org.springframework.context.annotation.Condition;import org.springframework.context.annotation.ConditionContext;import org.springframework.core.type.AnnotatedTypeMetadata;/** * {@link AstrsomnAutoConfiguration} 启用条件：{@code astrsomn.enabled=true}（默认） * <p> * 且 {@code astrsomn.datasource.url} 已配置并为支持的 MySQL/H2 JDBC URL。 */public class AstrsomnStarterRuntimeCondition implements Condition {    @Override    public boolean matches(ConditionContext context, AnnotatedTypeMetadata metadata) {        Boolean enabled = context.getEnvironment().getProperty("astrsomn.enabled", Boolean.class, Boolean.TRUE);        if (!Boolean.TRUE.equals(enabled)) {            return false;        }        String jdbcUrl = context.getEnvironment().getProperty("astrsomn.datasource.url");        return JdbcUrlDbSupport.isSupportedJdbcUrl(jdbcUrl);    }}